const frame = msg.payload || msg;
let canId = frame.canid & 0x1FFFFFFF;
const data = frame.data || [];

let state = flow.get("containerBatteryState") || {
    kind: "ContainerBatteryState",
    version: 1,
    // Battery Status (0x18FF14F0)
    socPercent: null,
    sohPercent: null,
    cycleCount: null,
    remainingEnergyKwh: null,
    availableEnergyKwh: null,
    // Cell Status (0x18FF11F0)
    totalVoltageV: null,
    currentA: null,
    selectedBmuLoc: null,
    selectedCellLoc: null,
    cellVoltageMv: null,
    cellTempC: null,
    // Max/Min Voltage Status (0x18FF12F0)
    maxCellVoltageCellLoc: null,
    maxCellVoltageBmuLoc: null,
    minCellVoltageCellLoc: null,
    minCellVoltageBmuLoc: null,
    avgCellVoltageMv: null,
    maxCellVoltageMv: null,
    minCellVoltageMv: null,
    // State Message (0x18FF10F0)
    stateCode: null,
    state: null,
    contactStatusPos: null,
    contactFbkPos: null,
    contactFbkNeg: null,
    chargeComplete: null,
    dischargeComplete: null,
    contactStatusNeg: null,
    isolationStatus: null,
    fuseFbk: null,
    input1Status: null,
    ambientTempC: null,
    dmccA: null,
    dmdcA: null,
    // Status2 (0x18FF13F0)
    maxCellTempCellLoc: null,
    maxCellTempBmuLoc: null,
    minCellTempCellLoc: null,
    minCellTempBmuLoc: null,
    maxCellTempC: null,
    minCellTempC: null,
    outVoltPosV: null,
    outVoltNegV: null
};

// Helper functions
function u8(buf, offset) {
    return buf[offset] & 0xFF;
}

function u16(buf, offset) {
    return (buf[offset] & 0xFF) | ((buf[offset + 1] & 0xFF) << 8);
}

function getNibbleLow(buf, offset) {
    return buf[offset] & 0x0F;
}

function getNibbleHigh(buf, offset) {
    return (buf[offset] >> 4) & 0x0F;
}

function getBit(buf, byteOffset, bitOffset) {
    return (buf[byteOffset] >> bitOffset) & 0x01;
}

function getBits(buf, byteOffset, bitOffset, length) {
    return (buf[byteOffset] >> bitOffset) & ((1 << length) - 1);
}

// State code to string mapping
const stateMap = {
    0: "N/A",
    101: "Standby",
    102: "Startup",
    103: "Precharge",
    104: "Discharge",
    105: "Charge",
    106: "Shutdown",
    107: "Fault",
    108: "Charge_Complete",
    109: "Discharge_Complete"
};

var processed = false;

// ==================== BCU_01_Battery_Status (0x18FF14F0) ====================
if (canId === 0x18FF14F0) {
    processed = true;
    // Bit 0-7: SOC (8 bit, Factor: 1, Offset: 0)
    state.socPercent = u8(data, 0);
    // Bit 8-15: SOH (8 bit, Factor: 1, Offset: 0)
    state.sohPercent = u8(data, 1);
    // Bit 16-31: Duty Cycle (16 bit, Factor: 1, Offset: 0)
    state.cycleCount = u16(data, 2);
    // Bit 32-47: Remaining Energy (16 bit, Factor: 0.01, Offset: 0)
    state.remainingEnergyKwh = u16(data, 4) * 0.01;
    // Bit 48-63: Available Energy (16 bit, Factor: 0.01, Offset: 0)
    state.availableEnergyKwh = u16(data, 6) * 0.01;
}

// ==================== BCU_01_Cell_Status (0x18FF11F0) ====================
if (canId === 0x18FF11F0) {
    processed = true;
    // Bit 0-15: Total Voltage (16 bit, Factor: 0.1, Offset: 0)
    state.totalVoltageV = u16(data, 0) * 0.1;
    // Bit 16-31: Instant Current (16 bit, Factor: 0.1, Offset: -1000)
    state.currentA = (u16(data, 2) * 0.1) - 1000;
    // Bit 32-35: Selected BMU Location (4 bit)
    state.selectedBmuLoc = getNibbleLow(data, 4);
    // Bit 36-39: Selected Cell Location (4 bit)
    state.selectedCellLoc = getNibbleHigh(data, 4);
    // Bit 40-55: Cell Voltage (16 bit, Factor: 1, Offset: 0)
    state.cellVoltageMv = u16(data, 5);
    // Bit 56-63: Cell Temp (8 bit, Factor: 1, Offset: -40)
    state.cellTempC = u8(data, 7) - 40;
}

// ==================== BCU_01_Max_Min_Voltage_Status (0x18FF12F0) ====================
if (canId === 0x18FF12F0) {
    processed = true;
    // Bit 0-3: Max Voltage Cell Location (4 bit)
    state.maxCellVoltageCellLoc = getNibbleLow(data, 0);
    // Bit 4-7: Max Voltage BMU Location (4 bit)
    state.maxCellVoltageBmuLoc = getNibbleHigh(data, 0);
    // Bit 8-11: Min Voltage Cell Location (4 bit)
    state.minCellVoltageCellLoc = getNibbleLow(data, 1);
    // Bit 12-15: Min Voltage BMU Location (4 bit)
    state.minCellVoltageBmuLoc = getNibbleHigh(data, 1);
    // Bit 16-31: Average Cell Voltage (16 bit, Factor: 1, Offset: 0)
    state.avgCellVoltageMv = u16(data, 2);
    // Bit 32-47: Max Cell Voltage (16 bit, Factor: 1, Offset: 0)
    state.maxCellVoltageMv = u16(data, 4);
    // Bit 48-63: Min Cell Voltage (16 bit, Factor: 1, Offset: 0)
    state.minCellVoltageMv = u16(data, 6);
}

// ==================== BCU_01_State_Message (0x18FF10F0) ====================
if (canId === 0x18FF10F0) {
    processed = true;
    // Bit 0-7: BCU State Code (8 bit)
    state.stateCode = u8(data, 0);
    state.state = stateMap[state.stateCode] || "Unknown";
    // Bit 8: Contact Status POS (1 bit)
    state.contactStatusPos = getBit(data, 1, 0);
    // Bit 9: Contact FBK POS (1 bit)
    state.contactFbkPos = getBit(data, 1, 1);
    // Bit 10: Contact FBK NEG (1 bit)
    state.contactFbkNeg = getBit(data, 1, 2);
    // Bit 11: Charge Complete (1 bit)
    state.chargeComplete = getBit(data, 1, 3) === 1;
    // Bit 12: Discharge Complete (1 bit)
    state.dischargeComplete = getBit(data, 1, 4) === 1;
    // Bit 13: Contact Status NEG (1 bit)
    state.contactStatusNeg = getBit(data, 1, 5);
    // Bit 14-15: Isolation Status (2 bit)
    state.isolationStatus = getBits(data, 1, 6, 2);
    // Bit 16-17: Fuse FBK (2 bit)
    state.fuseFbk = getBits(data, 2, 0, 2);
    // Bit 18-19: Input1 Status (2 bit)
    state.input1Status = getBits(data, 2, 2, 2);
    // Bit 24-31: Ambient Temp (8 bit, Factor: 1, Offset: -40)
    state.ambientTempC = u8(data, 3) - 40;
    // Bit 32-47: DMCC (16 bit, Factor: 0.1, Offset: 0)
    state.dmccA = u16(data, 4) * 0.1;
    // Bit 48-63: DMDC (16 bit, Factor: 0.1, Offset: 0)
    state.dmdcA = u16(data, 6) * 0.1;
}

// ==================== BCU_01_Status2 (0x18FF13F0) ====================
if (canId === 0x18FF13F0) {
    processed = true;
    // Bit 0-3: Max Temp Cell Location (4 bit)
    state.maxCellTempCellLoc = getNibbleLow(data, 0);
    // Bit 4-7: Max Temp BMU Location (4 bit)
    state.maxCellTempBmuLoc = getNibbleHigh(data, 0);
    // Bit 8-11: Min Temp Cell Location (4 bit)
    state.minCellTempCellLoc = getNibbleLow(data, 1);
    // Bit 12-15: Min Temp BMU Location (4 bit)
    state.minCellTempBmuLoc = getNibbleHigh(data, 1);
    // Bit 16-23: Max Cell Temp (8 bit, Factor: 1, Offset: -40)
    state.maxCellTempC = u8(data, 2) - 40;
    // Bit 24-31: Min Cell Temp (8 bit, Factor: 1, Offset: -40)
    state.minCellTempC = u8(data, 3) - 40;
    // Bit 32-47: OutVolt POS (16 bit, Factor: 0.1, Offset: 0)
    state.outVoltPosV = u16(data, 4) * 0.1;
    // Bit 48-63: OutVolt NEG (16 bit, Factor: 0.1, Offset: 0)
    state.outVoltNegV = u16(data, 6) * 0.1;
}

if (!processed) {
    return null;
}

state.timestampUtc = new Date().toISOString();
flow.set("containerBatteryState", state);
msg.payload = state;
return msg;

var state = flow.get("containerBatteryState");
if (state) {
    msg.payload = state;
    return msg;
}
msg.payload = { error: "No data yet" };
return msg;
